package br.com.aetherworld.data;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
public record PlayerProfile(int level,int expCurrent,int expMax,int freeAttributePoints,int ps,double mana,double manaMax,int forStat,int agi,int vit,int intelligence,int per){
 public static final Codec<PlayerProfile> CODEC=RecordCodecBuilder.create(i->i.group(Codec.INT.fieldOf("level").forGetter(PlayerProfile::level),Codec.INT.fieldOf("exp_current").forGetter(PlayerProfile::expCurrent),Codec.INT.fieldOf("exp_max").forGetter(PlayerProfile::expMax),Codec.INT.fieldOf("free_attribute_points").forGetter(PlayerProfile::freeAttributePoints),Codec.INT.fieldOf("ps").forGetter(PlayerProfile::ps),Codec.DOUBLE.fieldOf("mana").forGetter(PlayerProfile::mana),Codec.DOUBLE.fieldOf("mana_max").forGetter(PlayerProfile::manaMax),Codec.INT.fieldOf("for").forGetter(PlayerProfile::forStat),Codec.INT.fieldOf("agi").forGetter(PlayerProfile::agi),Codec.INT.fieldOf("vit").forGetter(PlayerProfile::vit),Codec.INT.fieldOf("int").forGetter(PlayerProfile::intelligence),Codec.INT.fieldOf("per").forGetter(PlayerProfile::per)).apply(i,PlayerProfile::new));
 public static final StreamCodec<RegistryFriendlyByteBuf,PlayerProfile> STREAM_CODEC=StreamCodec.composite(ByteBufCodecs.INT,PlayerProfile::level,ByteBufCodecs.INT,PlayerProfile::expCurrent,ByteBufCodecs.INT,PlayerProfile::expMax,ByteBufCodecs.INT,PlayerProfile::freeAttributePoints,ByteBufCodecs.INT,PlayerProfile::ps,ByteBufCodecs.DOUBLE,PlayerProfile::mana,ByteBufCodecs.DOUBLE,PlayerProfile::manaMax,ByteBufCodecs.INT,PlayerProfile::forStat,ByteBufCodecs.INT,PlayerProfile::agi,ByteBufCodecs.INT,PlayerProfile::vit,ByteBufCodecs.INT,PlayerProfile::intelligence,ByteBufCodecs.INT,PlayerProfile::per,PlayerProfile::new);
 public static PlayerProfile defaults(){return new PlayerProfile(1,0,150,0,0,100.0,200.0,10,10,10,10,10);}
 public PlayerProfile normalize(){int e=level*150;double mmax=100.0+intelligence*10.0;double m=Math.max(0.0,Math.min(mana,mmax));return new PlayerProfile(level,expCurrent,e,freeAttributePoints,ps,m,mmax,forStat,agi,vit,intelligence,per);}
}